head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.secugrpId = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = async function(e) {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92017_1.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화
 * @returns {void}
 * @hidden N
 */
scwin.init = async function () {
    scwin.secugrpId = $c.data.getParameter("secugrpId");;
    await scwin.search();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ibx_coSnm_onkeydown
 * @description ibx_coSnm 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ibx_coSnm_onkeydown = async function(e) {
    try {
        // 기업명 엔터
        if (e.keyCode === 13) {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92017_1.ibx_coSnm_onkeydown" });
    }
};

/**
 * @method
 * @name img_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_Search_onclick = async function (e) {
    try {
        // 조회 버튼 클릭
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92017_1.img_Search_onclick" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description img_Close 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_Close_onclick = function (e) {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92017_1.img_Close_onclick" });
    }
};

/**
 * @method
 * @name txb_Search_onkeydown
 * @description txb_Search 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.txb_Search_onkeydown = async function (e) {
    try {
        // 기업명 엔터
        if (e.keyCode === 13) {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92017_1.txb_Search_onkeydown" });
    }
};

/**
 * @method
 * @name grd_IsuInst_oncelldblclick
 * @description grd_IsuInst 셀 더블클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_IsuInst_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.setParam(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92017_1.grd_IsuInst_oncelldblclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 기업목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.initDs();
    dma_searchReq.set("spotIsuTrdMktTpCd", $c.session.getUserInfo("market"));
    dma_searchReq.set("secugrpId", scwin.secugrpId);
    dma_searchReq.set("isuKorNm", ibx_isuKorNm.getValue());

    const sbmOptions = {
        id: "sbm_isuList",
        action: "/api/listing/common/pop/isu/select-list-secuisu-all",
        method: "get",
        ref: "dma_searchReq",
        target: "dlt_listRes=body",
    };
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result.responseJSON.success) {
        txb_TotCnt.setValue(dlt_listRes.getRowCount());
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dlt_listRes.removeAll();
    txb_TotCnt.setValue("0");
};

/**
 * @method
 * @name setParam
 * @description 선택된 값을 오프너에 전달한다.
 * @param {*} v_Currow v_Currow
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function(v_Currow) {

    if (v_Currow === undefined) {
        v_Currow = dlt_listRes.getRowPosition();
    }
    const res = dlt_listRes.getRowJSON(v_Currow);
    $c.win.closePopup(res);
};

/**
 * @method
 * @name isuKorNm_customFormatter
 * @description 종목명 컬럼 표시 포맷
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @returns {*}
 * @hidden N
 */
scwin.isuKorNm_customFormatter = function (data, formattedData, rowIndex, columnIndex) {
    let listStatCd = dlt_listRes.getCellData(rowIndex, "listStatCd");
    if (listStatCd === "D") {
        grd_IsuInst.setCellColor(rowIndex, "isuKorNm", "red");
    }
    return formattedData;
};
